// Function node "ingest config". In: retained zigdash/alerts/config.
// Keeps the config and an index from device state topic to the alerts that
// watch it. An empty payload (ZigDash turned alerts off) drops everything.
const raw = msg.payload;
const empty = raw === undefined || raw === null ||
    (typeof raw === 'string' && raw.trim() === '') ||
    (Buffer.isBuffer(raw) && raw.length === 0);
if (empty) {
    flow.set('cfg', null);
    flow.set('index', {});
    return null;
}
const cfg = (typeof raw === 'object' && !Buffer.isBuffer(raw)) ? raw : JSON.parse(raw.toString());
const index = {};
for (const a of cfg.alerts || []) {
    if (a.enabled === false) continue;
    for (const d of a.devices || []) {
        if (!d.topic) continue;
        (index[d.topic] = index[d.topic] || []).push({
            id: a.id, kind: a.kind, from: a.from, to: a.to,
            threshold: a.threshold === undefined ? 20 : a.threshold,
            ieee: d.ieee, name: d.name,
        });
    }
}
flow.set('cfg', cfg);
flow.set('index', index);
flow.set('jwts', {}); // a new config may carry new keys
// Forget devices that are no longer watched.
const mem = flow.get('mem') || {};
let changed = false;
for (const t of Object.keys(mem)) if (!index[t]) { delete mem[t]; changed = true; }
if (changed) {
    flow.set('mem', mem);
    return { topic: 'zigdash/alerts/state', retain: true,
             payload: JSON.stringify({ mem, dead: flow.get('dead') || {} }) };
}
return null;

// Function node "restore memory". In: retained zigdash/alerts/state.
// Node-RED's context on the hub is memory only, so what the flow remembers
// (each device's last values, which batteries were reported, dead phones)
// comes back from the broker once, on start.
if (flow.get('memLoaded')) return null;
flow.set('memLoaded', true);
const raw = msg.payload;
if (raw === undefined || raw === null || raw === '' || (Buffer.isBuffer(raw) && raw.length === 0)) return null;
try {
    const s = (typeof raw === 'object' && !Buffer.isBuffer(raw)) ? raw : JSON.parse(raw.toString());
    flow.set('mem', s.mem || {});
    flow.set('dead', s.dead || {});
} catch (e) {
    node.warn('alerts: bad state ' + e);
}
return null;

// Function node "watch devices". In: every message under the Home's
// Zigbee2MQTT base topic. Out 1: alert events to send. Out 2: retained
// state and recent-alerts publishes. Fires on changes, never on values:
// Zigbee2MQTT republishes a device's whole state whenever anything asks.
const index = flow.get('index') || {};
const cfg = flow.get('cfg');
const topic = msg.topic;
if (!cfg || topic.endsWith('/set') || topic.endsWith('/get') || topic.includes('/bridge/')) return null;
const hits = index[topic];
if (!hits) return null;
let state;
try {
    const raw = msg.payload;
    state = (typeof raw === 'object' && !Buffer.isBuffer(raw)) ? raw : JSON.parse(raw.toString());
} catch (e) { return null; }
if (!state || typeof state !== 'object') return null;

const mem = flow.get('mem') || {};
const fresh = !mem[topic];           // first sight since the flow (re)started with no memory
const m = mem[topic] || (mem[topic] = {});
const now = new Date();
const hhmm = now.toLocaleTimeString('en-GB', { timeZone: cfg.timeZone || 'UTC', hour12: false }).slice(0, 5);
const within = (from, to) => {
    if (!from || !to) return true;
    return from <= to ? (hhmm >= from && hhmm < to) : (hhmm >= from || hhmm < to);
};
const events = [];
let changed = false;
const event = (h, kind, cleared, value) => ({
    v: 1, kind, connection: cfg.connection || null, device: h.ieee, name: h.name, home: cfg.home, cleared,
    value: value === undefined ? null : value,
    at: now.toISOString(),
});

for (const h of hits) {
    switch (h.kind) {
        case 'leak':
        case 'smoke': {
            const v = h.kind === 'leak' ? state.water_leak : state.smoke;
            if (typeof v !== 'boolean') break;
            const was = m[h.kind];
            if (was === undefined ? (fresh && v) : v !== was) events.push(event(h, h.kind, !v));
            if (was !== v) { m[h.kind] = v; changed = true; }
            break;
        }
        case 'opened': {
            const v = state.contact;
            if (typeof v !== 'boolean') break;
            // contact: true = closed. An opening is closed -> open.
            if (m.contact === true && v === false && within(h.from, h.to)) events.push(event(h, 'opened', false));
            if (m.contact !== v) { m.contact = v; changed = true; }
            break;
        }
        case 'battery': {
            const level = typeof state.battery === 'number' ? state.battery : undefined;
            const flag = state.battery_low;
            if (level === undefined && typeof flag !== 'boolean') break;
            const low = flag === true || (level !== undefined && level <= h.threshold);
            const was = m.batteryLow;
            if (low && (was === false || (was === undefined && fresh))) events.push(event(h, 'battery', false, level));
            if (was !== low) { m.batteryLow = low; changed = true; }
            break;
        }
    }
}
if (fresh) changed = true;
flow.set('mem', mem);

const out2 = [];
if (changed) {
    out2.push({ topic: 'zigdash/alerts/state', retain: true,
                payload: JSON.stringify({ mem, dead: flow.get('dead') || {} }) });
}
if (events.length) {
    const recent = [...events.slice().reverse(), ...(flow.get('recent') || [])].slice(0, 20);
    flow.set('recent', recent);
    out2.push({ topic: 'zigdash/alerts/recent', retain: true, payload: JSON.stringify(recent) });
}
return [events.map(e => ({ payload: e })), out2];

// Function node "test". In: zigdash/alerts/test, {"phone": "<id>"} or {}.
// Sends a test alert to that phone, or to every channel.
const cfg = flow.get('cfg');
if (!cfg) return null;
let req = {};
try { req = typeof msg.payload === 'object' && !Buffer.isBuffer(msg.payload) ? msg.payload : JSON.parse(msg.payload.toString() || '{}'); } catch (e) {}
return { onlyPhone: req.phone || null,
         payload: { v: 1, kind: 'test', connection: cfg.connection || null, device: null, name: 'ZigDash', home: cfg.home,
                    cleared: false, value: null,
                    at: new Date().toISOString() } };

// Function node "send". In: one alert event (msg.payload). Out: one HTTP
// request per phone (Web Push, RFC 8291 aes128gcm + VAPID ES256, built-in
// crypto only), plus ntfy and Pushover when set. msg.onlyPhone limits a
// test to one phone.
const cfg = flow.get('cfg');
if (!cfg) return null;
const ev = msg.payload;
const dead = flow.get('dead') || {};
const b64 = s => Buffer.from(s, 'base64url');
const out = [];

const text = () => {
    const key = ev.kind === 'test' ? 'test' : ev.cleared ? ev.kind + 'Cleared' : ev.kind;
    const t = (cfg.text || {})[key] || key;
    return t.replace('{name}', cfg.hideNames ? '' : (ev.name || '')).replace('{home}', ev.home || '')
            .replace('{value}', ev.value === null || ev.value === undefined ? '' : String(ev.value))
            .replace(/\s+/g, ' ').replace(/\(\s*\)/, '').trim();
};

// Web Push to each phone.
if (cfg.vapid && cfg.vapid.privateJwk) {
    const key = crypto.createPrivateKey({ key: cfg.vapid.privateJwk, format: 'jwk' });
    const enc = o => Buffer.from(JSON.stringify(o)).toString('base64url');
    // Signed tokens are kept for a while, per push server and per key: a
    // token signed with an old key pair would be refused ("invalid JWT").
    const jwts = flow.get('jwts') || {};
    const nowS = Math.floor(Date.now() / 1000);
    const jwtFor = origin => {
        const c = jwts[origin + '|' + cfg.vapid.publicKey];
        if (c && c.exp - nowS > 3600) return c.jwt;
        const exp = nowS + 12 * 3600;
        const unsigned = enc({ typ: 'JWT', alg: 'ES256' }) + '.' +
            enc({ aud: origin, exp, sub: 'mailto:alerts@zigdash.app' });
        const sig = crypto.sign('sha256', Buffer.from(unsigned), { key, dsaEncoding: 'ieee-p1363' }).toString('base64url');
        jwts[origin + '|' + cfg.vapid.publicKey] = { jwt: unsigned + '.' + sig, exp };
        return jwts[origin + '|' + cfg.vapid.publicKey].jwt;
    };
    const plain = Buffer.from(JSON.stringify(ev));
    for (const p of cfg.phones || []) {
        if (dead[p.id] || !p.endpoint || !p.p256dh || !p.auth) continue;
        if (msg.onlyPhone && p.id !== msg.onlyPhone) continue;
        const uaPub = b64(p.p256dh), auth = b64(p.auth);
        const ecdh = crypto.createECDH('prime256v1'); ecdh.generateKeys();
        const asPub = ecdh.getPublicKey();
        const secret = ecdh.computeSecret(uaPub);
        const salt = crypto.randomBytes(16);
        const ikm = Buffer.from(crypto.hkdfSync('sha256', secret, auth, Buffer.concat([Buffer.from('WebPush: info\0'), uaPub, asPub]), 32));
        const cek = Buffer.from(crypto.hkdfSync('sha256', ikm, salt, Buffer.from('Content-Encoding: aes128gcm\0'), 16));
        const nonce = Buffer.from(crypto.hkdfSync('sha256', ikm, salt, Buffer.from('Content-Encoding: nonce\0'), 12));
        const c = crypto.createCipheriv('aes-128-gcm', cek, nonce);
        const body = Buffer.concat([c.update(Buffer.concat([plain, Buffer.from([2])])), c.final(), c.getAuthTag()]);
        const rs = Buffer.alloc(4); rs.writeUInt32BE(4096);
        const origin = new URL(p.endpoint).origin;
        out.push({
            url: p.endpoint, method: 'POST', phone: p.id, isTest: ev.kind === 'test',
            headers: { 'Content-Encoding': 'aes128gcm', 'TTL': '86400', 'Urgency': 'high',
                       'Authorization': 'vapid t=' + jwtFor(origin) + ',k=' + cfg.vapid.publicKey },
            payload: Buffer.concat([salt, rs, Buffer.from([65]), asPub, body]),
        });
    }
    flow.set('jwts', jwts);
}

const urgent = ev.kind === 'leak' || ev.kind === 'smoke';
if (cfg.ntfy && cfg.ntfy.topic && !msg.onlyPhone) {
    out.push({
        url: (cfg.ntfy.server || 'https://ntfy.sh').replace(/\/$/, '') + '/' + cfg.ntfy.topic,
        method: 'POST', channel: 'ntfy', isTest: ev.kind === 'test',
        headers: { 'Title': ev.home || 'ZigDash', 'Priority': urgent && !ev.cleared ? '5' : '4', 'Tags': 'zigdash' },
        payload: text(),
    });
}
if (cfg.pushover && cfg.pushover.user && cfg.pushover.token && !msg.onlyPhone) {
    const m = { token: cfg.pushover.token, user: cfg.pushover.user, title: ev.home || 'ZigDash', message: text(),
                priority: urgent && !ev.cleared ? 2 : 1 };
    if (m.priority === 2) { m.retry = 60; m.expire = 3600; }
    out.push({ url: 'https://api.pushover.net/1/messages.json', method: 'POST', channel: 'pushover',
               isTest: ev.kind === 'test', headers: { 'Content-Type': 'application/json' }, payload: m });
}
return [out];

// Function node "result". In: the HTTP answer. A 404 or 410 from Google's
// push means that phone's registration is gone: mark it dead (ZigDash
// removes it from the config). A test reports its result to ZigDash.
const status = msg.statusCode;
const out = [];
if (msg.phone && (status === 404 || status === 410)) {
    const dead = flow.get('dead') || {};
    if (!dead[msg.phone]) {
        dead[msg.phone] = true;
        flow.set('dead', dead);
        out.push({ topic: 'zigdash/alerts/state', retain: true,
                   payload: JSON.stringify({ mem: flow.get('mem') || {}, dead }) });
    }
}
if (msg.isTest) {
    out.push({ topic: 'zigdash/alerts/test/result', retain: false,
               payload: JSON.stringify({ phone: msg.phone || null, channel: msg.channel || 'push',
                                         status, ok: status >= 200 && status < 300,
                                         body: String(msg.payload || '').slice(0, 200) }) });
}
if (status < 200 || status >= 300) node.warn('alerts: ' + (msg.channel || 'push') + ' answered ' + status);
return [out];
